# Builds the TITANIUM war-walker (popup-marine-titanium-24bone.glb) that
# squads of an empire owning a Titanium Weapons Factory field instead of
# standard marines -- see
# packages/client/src/client-map-3d-popup-marine/popup-marine-armor.ts.
#
# Inputs, all from Meshy (none checked into the repo):
#   - the auto-rigged walker (a sealed drum-hull walker with a laser gatling
#     and a buzz-saw claw, Meshy's 24-bone biped template), and
#   - its own animation clips, generated by Meshy's animate API ON THAT SAME
#     RIG, so they share its rest pose and need no retargeting. Each is a
#     <name>.glb in <clip-dir>; CLIPS below maps the game's clip slots onto
#     them.
#
# The game looks clips up by the STANDARD marine's names (MARINE_CLIP_NAMES
# in popup-marine-asset.ts, plus PistolWalk for the muster march), so the
# walker's clips are exported under those slot names: "PistolKneelingIdle"
# is the same braced firing stance as "PistolIdle" here, not a kneel. MeleeSwing is extra, for
# close combat; nothing plays it yet.
#
# Mesh: Meshy's walker is millions of triangles in hundreds of loose shells
# (rivets, cables, saw teeth). Decimating that to the instance budget
# shatters it into shards, so the body is VOXEL-REMESHED into one closed
# shell first, then decimated, and the rig's skin weights are copied back
# from the full-detail mesh (Data Transfer, nearest face interpolated).
#
# Everything after that mirrors bake-popup-marine-titan-model.py
# (object-level fcurve drop, Hips root-motion strip, per-clip slot binding,
# root-node scale, greyscale per-bone vertex paint, ACTIONS export) -- read
# that file's comments for the Blender 5.x glTF traps each step avoids.
#
# Run (Blender 5.x, or `python -I` with the bpy wheel):
#   blender --background --python bake-popup-marine-titanium-model.py -- \
#     <meshy-rigged-walker.glb> <clip-dir> <out.glb> [targetTriangleCount]
import os
import sys
import bpy

argv = sys.argv[sys.argv.index("--") + 1:]
SRC_RIG = argv[0]
CLIP_DIR = argv[1]
OUT = argv[2]
TARGET_TRIS = int(argv[3]) if len(argv) > 3 else 6000
# The standard marine's height (0.052 local units). The walker already
# reads as far heavier than infantry -- with its shoulder plates and weapon
# arms it is about twice a marine's width -- and the squad formation spaces
# eight figures for marine-width bodies: at 1.4x height (tried first) the
# squad merged into one solid wall in the battle overlay.
TARGET_HEIGHT = 0.052
# Voxel size as a fraction of the walker's height; fine enough to keep the
# gatling barrels, saw and cooling stacks readable at the triangle budget.
VOXEL_DIVISIONS = 220

# (game clip slot, Meshy clip file stem, strip horizontal root motion?)
CLIPS = [
    ("PistolRun", "WalkerAdvance", True),        # Carry Heavy Cannon Forward (action 550)
    ("PistolIdle", "WalkerIdle", True),          # Combat Idle (action 89)
    # The kneel slot reuses Combat Idle: a walker doesn't take cover, and
    # Side Shot (action 104, also tried) sank the hull and aimed sideways.
    ("PistolKneelingIdle", "WalkerIdle", True),
    ("PistolWalk", "WalkerWalk", True),          # the rig task's bundled walking clip
    ("MeleeSwing", "MeleeSwing", True),          # Heavy Hammer Swing (action 128)
]

# The clips are humanoid, so they bend the spine like a torso -- which
# crumples a sealed drum hull. Worse, Meshy's biped auto-rig doesn't fit a
# headless drum: it skins most of the hull (and the shoulder plates) to the
# two SHOULDER bones, so every arm swing bent the drum too. The hull is made
# rigid instead: every vertex whose dominant bone is a spine/head bone or a
# shoulder bone is skinned 100% to HULL_BONE, and the clips' rotation
# channels for the hips and spine/head bones are dropped, so the drum stays
# level instead of leaning, twisting and tumbling like a person (the hips
# carry the biggest of those body turns). Shoulder rotation is KEPT -- it
# still swings the arms, whose own bones keep Meshy's weights -- and the
# legs keep stepping relative to the level hips.
SPINE_BONES = {"Hips", "Spine", "Spine01", "Spine02", "neck", "Head", "head_end", "headfront"}
HULL_BONES = SPINE_BONES | {"LeftShoulder", "RightShoulder"}
HULL_BONE = "Spine02"


def import_glb(path):
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    return [o for o in bpy.data.objects if o not in before]


bpy.ops.wm.read_factory_settings(use_empty=True)

# --- Base: the rigged walker. Drop its importer bone-shape spheres and any
# clip Meshy baked in. ---
base_objects = import_glb(SRC_RIG)
armature = next(o for o in base_objects if o.type == "ARMATURE")
source_mesh = next(o for o in base_objects if o.type == "MESH" and o.find_armature() == armature)
for o in base_objects:
    if o.type == "MESH" and o != source_mesh:
        bpy.data.objects.remove(o, do_unlink=True)
for action in list(bpy.data.actions):
    bpy.data.actions.remove(action)
armature.animation_data_create()
armature.animation_data.action = None

# --- Clips: steal each file's action, drop its objects. ---
imported = []
for label, stem, strip_root_motion in CLIPS:
    before_actions = set(bpy.data.actions)
    clip_objects = import_glb(os.path.join(CLIP_DIR, stem + ".glb"))
    new_actions = set(bpy.data.actions) - before_actions
    action = max(new_actions, key=lambda a: a.frame_range[1] - a.frame_range[0])
    action.name = label
    action.use_fake_user = True
    # Unique slot name per clip -- shared slot names make the exporter bake
    # every clip as the same data (see the standard bake script).
    for slot in action.slots:
        slot.name_display = f"{label}Pose"
    for stray in new_actions - {action}:
        bpy.data.actions.remove(stray)
    for o in clip_objects:
        bpy.data.objects.remove(o, do_unlink=True)
    imported.append((label, action, strip_root_motion))
    print(f"imported {label} <- {stem}: frames {tuple(action.frame_range)}")

# --- Bind each clip to this armature's own slot; drop object-level
# channels (they would overwrite the root-node scale at runtime) and strip
# Hips X/Y so every clip animates in place. ---
for label, action, strip_root_motion in imported:
    armature.animation_data.action = action
    slot = armature.animation_data.action_suitable_slots[0]
    armature.animation_data.action_slot = slot
    for layer in action.layers:
        for strip in layer.strips:
            channelbag = strip.channelbag(slot)
            if channelbag is None:
                continue
            for fcurve in list(channelbag.fcurves):
                object_level = not fcurve.data_path.startswith("pose.bones[")
                root_motion = (
                    strip_root_motion
                    and fcurve.data_path == 'pose.bones["Hips"].location'
                    and fcurve.array_index in (0, 1)
                )
                hull_bend = any(
                    fcurve.data_path in (f'pose.bones["{bone}"].rotation_quaternion', f'pose.bones["{bone}"].rotation_euler')
                    for bone in SPINE_BONES
                )
                if object_level or root_motion or hull_bend:
                    channelbag.fcurves.remove(fcurve)
armature.animation_data.action = None

# --- Voxel remesh + decimate a copy, then transfer the skin weights. ---
mesh = source_mesh.copy()
mesh.data = source_mesh.data.copy()
bpy.context.collection.objects.link(mesh)
for modifier in list(mesh.modifiers):
    mesh.modifiers.remove(modifier)
mesh.vertex_groups.clear()
local_height = max(v.co.z for v in mesh.data.vertices) - min(v.co.z for v in mesh.data.vertices)
bpy.context.view_layer.objects.active = mesh
remesh = mesh.modifiers.new(name="Remesh", type="REMESH")
remesh.mode = "VOXEL"
remesh.voxel_size = local_height / VOXEL_DIVISIONS
bpy.ops.object.modifier_apply(modifier=remesh.name)
voxel_tris = sum(len(p.vertices) - 2 for p in mesh.data.polygons)
decimate = mesh.modifiers.new(name="Decimate", type="DECIMATE")
decimate.ratio = min(1.0, TARGET_TRIS / max(1, voxel_tris))
bpy.ops.object.modifier_apply(modifier=decimate.name)
print(f"voxel tris {voxel_tris} -> {sum(len(p.vertices) - 2 for p in mesh.data.polygons)}")

for group in source_mesh.vertex_groups:
    mesh.vertex_groups.new(name=group.name)
transfer = mesh.modifiers.new(name="Weights", type="DATA_TRANSFER")
transfer.object = source_mesh
transfer.use_vert_data = True
transfer.data_types_verts = {"VGROUP_WEIGHTS"}
transfer.vert_mapping = "POLYINTERP_NEAREST"
transfer.layers_vgroup_select_src = "ALL"
transfer.layers_vgroup_select_dst = "NAME"
bpy.ops.object.modifier_apply(modifier=transfer.name)

hull_index = mesh.vertex_groups[HULL_BONE].index
hull_group_indices = {g.index for g in mesh.vertex_groups if g.name in HULL_BONES}
rigid = 0
for vertex in mesh.data.vertices:
    best = max(vertex.groups, key=lambda g: g.weight, default=None)
    if best is None or best.group not in hull_group_indices:
        continue
    for g in list(vertex.groups):
        mesh.vertex_groups[g.group].remove([vertex.index])
    mesh.vertex_groups[hull_index].add([vertex.index], 1.0, "REPLACE")
    rigid += 1
print(f"rigid hull: {rigid} verts skinned to {HULL_BONE}")
skin = mesh.modifiers.new(name="Armature", type="ARMATURE")
skin.object = armature
bpy.data.objects.remove(source_mesh, do_unlink=True)
mesh.name = "char1"
mesh.data.materials.clear()  # shaded purely by vertex colour x team tint

# --- Root-node scale + recentre (UNAPPLIED, see the standard bake). ---
local = [v.co for v in mesh.data.vertices]
xs, ys, zs = ([v[i] for v in local] for i in range(3))
armature.rotation_mode = "QUATERNION"
armature.rotation_quaternion = (1, 0, 0, 0)
scale = TARGET_HEIGHT / (max(zs) - min(zs))
armature.scale = (scale, scale, scale)
armature.location = (-(min(xs) + max(xs)) / 2 * scale, -(min(ys) + max(ys)) / 2 * scale, -min(zs) * scale)
bpy.context.view_layer.update()
print(f"root-node scale {scale:.8f}")

# --- Greyscale per-bone paint: "how much team colour shows" (see the
# standard bake for the sRGB/linear band these values sit in). On the walker
# the rig's torso bones hold the drum hull and the shoulder bones the big
# shoulder plates -- the faction-colour surfaces -- while the weapon arms,
# piston legs and feet step down to graphite.
REGION_VALUES = {
    "LeftShoulder": 0.95, "RightShoulder": 0.95,
    "Spine02": 0.93, "neck": 0.90, "Head": 0.84, "head_end": 0.84, "headfront": 0.84,
    "Spine": 0.88, "Spine01": 0.90, "Hips": 0.66,
    "LeftArm": 0.72, "RightArm": 0.72,
    "LeftForeArm": 0.62, "RightForeArm": 0.62,
    "LeftHand": 0.50, "RightHand": 0.50,
    "LeftUpLeg": 0.60, "RightUpLeg": 0.60,
    "LeftLeg": 0.52, "RightLeg": 0.52,
    "LeftFoot": 0.44, "RightFoot": 0.44,
    "LeftToeBase": 0.40, "RightToeBase": 0.40,
}
DEFAULT_VALUE = 0.80
group_names = {g.index: g.name for g in mesh.vertex_groups}


def region_value(vertex) -> float:
    best = max(vertex.groups, key=lambda g: g.weight, default=None)
    if best is None:
        return DEFAULT_VALUE
    return REGION_VALUES.get(group_names.get(best.group, ""), DEFAULT_VALUE)


for layer in list(mesh.data.color_attributes):
    mesh.data.color_attributes.remove(layer)
vcol = mesh.data.vertex_colors.new(name="Col")
for poly in mesh.data.polygons:
    for li in poly.loop_indices:
        value = region_value(mesh.data.vertices[mesh.data.loops[li].vertex_index])
        vcol.data[li].color = (value, value, value, 1.0)

# --- Export. ---
bpy.ops.object.select_all(action="DESELECT")
mesh.select_set(True)
armature.select_set(True)
bpy.context.view_layer.objects.active = armature
bpy.ops.export_scene.gltf(
    filepath=OUT,
    export_format="GLB",
    use_selection=True,
    export_apply=False,
    export_skins=True,
    export_yup=True,
    export_vertex_color="ACTIVE",
    export_normals=True,
    export_texcoords=False,
    export_materials="NONE",
    export_animations=True,
    export_animation_mode="ACTIONS",
)
print("wrote", OUT)
